<?php
/** Approved Contact composition with Page copy, shared settings and email-only delivery. */
defined( 'ABSPATH' ) || exit;
$page = get_queried_object_id();
$email = showmakers_site_setting( 'contact_email' );
$phone = showmakers_site_setting( 'phone' );
$address = showmakers_site_setting( 'address' );
$line_1 = showmakers_page_copy( $page, 'contact_heading_line_1' );
$line_2 = showmakers_page_copy( $page, 'contact_heading_line_2' );
$intro_1 = showmakers_page_copy( $page, 'contact_intro_line_1' );
$intro_2 = showmakers_page_copy( $page, 'contact_intro_line_2' );
$token = showmakers_contact_token();
$states = array( 'ready' => '', 'validationError' => 'Please complete the required fields and check your email address.', 'unavailable' => 'Please contact us by email.', 'submitting' => 'Sending your inquiry…', 'success' => 'Thank you. Your inquiry has been sent.', 'error' => 'Your inquiry could not be sent. Please try again or email ' . $email . '.' );
?>
<section class="contact-opening"><div class="shell"><h1><?php if ( $line_1 !== '' ) : ?><span><?php echo esc_html( $line_1 ); ?></span><?php endif; if ( $line_2 !== '' ) : ?><span><?php echo esc_html( $line_2 ); ?></span><?php endif; if ( $line_1 === '' && $line_2 === '' ) echo esc_html( get_the_title( $page ) ); ?></h1><?php if ( $intro_1 !== '' || $intro_2 !== '' ) : ?><p><?php if ( $intro_1 !== '' ) : ?><span><?php echo esc_html( $intro_1 ); ?></span><?php endif; if ( $intro_2 !== '' ) : ?><span><?php echo esc_html( $intro_2 ); ?></span><?php endif; ?></p><?php endif; ?></div></section><div class="shell contact-layout"><section class="inquiry" aria-labelledby="inquiry-title"><h2 class="visually-hidden" id="inquiry-title">Tell us a little about you.</h2><form id="inquiry-form" data-endpoint="<?php echo esc_url( admin_url( 'admin-ajax.php' ) ); ?>" data-states="<?php echo esc_attr( wp_json_encode( $states ) ); ?>" data-state="ready" onsubmit="return false"><input type="hidden" name="action" value="showmakers_contact"><input type="hidden" name="contact_nonce" value="<?php echo esc_attr( wp_create_nonce( 'showmakers_contact' ) ); ?>"><input type="hidden" name="contact_token" value="<?php echo esc_attr( $token['contact_token'] ); ?>"><input type="hidden" name="contact_signature" value="<?php echo esc_attr( $token['contact_signature'] ); ?>"><div hidden aria-hidden="true"><label for="website_honeypot">Leave this empty</label><input id="website_honeypot" name="website_honeypot" type="text" tabindex="-1" autocomplete="off" value=""></div><div id="inquiry-context" data-projects="<?php echo esc_attr( wp_json_encode( showmakers_project_context_data() ) ); ?>"><div id="project-context" hidden><p>Project reference: <strong id="project-reference-title"></strong></p><button type="button" class="text-button" id="remove-project">Remove reference</button></div><input type="hidden" name="projectReference" id="projectReference" value=""><input type="hidden" name="sourcePage" id="sourcePage" value="/contact/"></div><div class="conversation-field field-name"><label for="name">Hi, my name is</label><input id="name" name="name" aria-describedby="name-error" required type="text" autocomplete="name" placeholder="Your name" maxlength="254"><p class="field-error" id="name-error" hidden></p></div><div class="conversation-field field-company"><label for="company">I’m from<span class="field-optional">Optional</span></label><input id="company" name="company" aria-describedby="company-error" type="text" autocomplete="organization" placeholder="Company / brand" maxlength="254"><p class="field-error" id="company-error" hidden></p></div><div class="conversation-field field-service"><label for="service">I’m looking for help with</label><select id="service" name="service" aria-describedby="service-error" required><option value="" disabled selected>Choose a service</option><?php foreach ( showmakers_visible_services() as $service ) : ?><option value="<?php echo esc_attr( $service->slug ); ?>"><?php echo esc_html( $service->name ); ?></option><?php endforeach; ?><option value="not-sure">Not sure yet</option></select><p class="field-error" id="service-error" hidden></p></div><div class="conversation-field field-goal"><label for="goal">I’m hoping to</label><textarea id="goal" name="goal" aria-describedby="goal-error" required rows="2" maxlength="6000" placeholder="Tell us what you’d like to achieve."></textarea><p class="field-error" id="goal-error" hidden></p></div><div class="conversation-field field-email"><label for="email">You can reach me at</label><input id="email" name="email" aria-describedby="email-error" required type="email" autocomplete="email" placeholder="Your email address" maxlength="254"><p class="field-error" id="email-error" hidden></p></div><div class="conversation-field field-additionalDetails"><label for="additionalDetails">Anything else we should know?<span class="field-optional">Optional</span></label><textarea id="additionalDetails" name="additionalDetails" aria-describedby="additionalDetails-error" rows="2" maxlength="6000" placeholder="A little more context, if you’d like."></textarea><p class="field-error" id="additionalDetails-error" hidden></p></div><div class="inquiry-actions"><button class="cta-reveal" type="submit" data-event="contact_submit" disabled>Send Inquiry<svg class="ui-arrow" viewBox="0 0 64 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="square" stroke-linejoin="miter"><path d="M2 8H60M54 2L60 8L54 14"/></svg></button><p class="privacy-acknowledgement">By submitting this form, you acknowledge our <a href="<?php echo esc_url( home_url( '/privacy/' ) ); ?>">Privacy Notice</a>.</p>
